'use client'

import * as React from 'react'

import './toast-stack.css'

export type Toast = {
    id: string | number
    title: React.ReactNode
    description?: React.ReactNode
}

export type ToastStackProps = {
    toasts: Toast[]
    onDismiss: (id: Toast['id']) => void
    /** Accessible name for the region. */
    label?: string
    /** Newest toasts fanned out in a stack; older ones tuck behind. */
    visible?: number
    className?: string
}

// A polite live region: new toasts are announced without stealing focus.
// Hovering or focusing the stack fans every toast out so all are reachable.
const ToastStack = ({ toasts, onDismiss, label = 'Notifications', visible = 3, className }: ToastStackProps) => {
    const ordered = [...toasts].reverse()

    return <section className={['rad-fx-toasts', className].filter(Boolean).join(' ')} aria-label={label}>
        <ol className="rad-fx-toasts-list" aria-live="polite" aria-relevant="additions">
            {ordered.map((toast, i) => (
                <li
                    key={toast.id}
                    className="rad-fx-toast"
                    style={{ '--rad-fx-toast-i': i, zIndex: ordered.length - i, opacity: i >= visible ? 0 : undefined } as React.CSSProperties}
                >
                    <div className="rad-fx-toast-text">
                        <p className="rad-fx-toast-title">{toast.title}</p>
                        {toast.description ? <p className="rad-fx-toast-description">{toast.description}</p> : null}
                    </div>
                    <button type="button" className="rad-fx-toast-close" aria-label="Dismiss notification" onClick={() => onDismiss(toast.id)}>
                        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 7 L17 17 M17 7 L7 17" /></svg>
                    </button>
                </li>
            ))}
        </ol>
    </section>
}

export default ToastStack

.rad-fx-toasts { width: 340px; }

.rad-fx-toasts-list {
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
}

.rad-fx-toast {
    grid-area: 1 / 1;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 14px 14px 16px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    background: #17171c;
    color: #f4f4f5;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
    /* Collapsed: each older toast peeks out a little behind the newest. */
    transform: translateY(calc(var(--rad-fx-toast-i, 0) * -10px)) scale(calc(1 - var(--rad-fx-toast-i, 0) * 0.05));
    transform-origin: 50% 0;
    transition: transform 400ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 300ms ease;
    animation: rad-fx-toast-in 450ms cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

/* Expanded on hover or focus: toasts fan out into a readable list. */
.rad-fx-toasts:hover .rad-fx-toast,
.rad-fx-toasts:focus-within .rad-fx-toast {
    transform: translateY(calc(var(--rad-fx-toast-i, 0) * -100% - var(--rad-fx-toast-i, 0) * 8px));
    opacity: 1 !important;
}

.rad-fx-toast-text { flex: 1; min-width: 0; }
.rad-fx-toast-title { margin: 0; font-weight: 600; font-size: 0.9rem; }
.rad-fx-toast-description { margin: 4px 0 0; font-size: 0.85rem; color: #c4c4cc; }

.rad-fx-toast-close {
    display: inline-flex;
    padding: 4px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.rad-fx-toast-close:focus-visible { outline: 2px solid currentColor; }

.rad-fx-toast-close svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

@keyframes rad-fx-toast-in {
    from { opacity: 0; transform: translateY(24px) scale(0.95); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-toast { animation: none; transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-toast { animation: none; transition: none; }
